SELECT md.chembl_id AS molecule_chembl_id, md.pref_name AS molecule_name, md.max_phase, md.molecule_type AS molecule_type, cs.canonical_smiles FROM docs d JOIN compound_records cr ON d.doc_id = cr.doc_id JOIN molecule_dictionary md ON cr.molregno = md.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE d.chembl_id = 'CHEMBL1125820' ORDER BY md.chembl_id ASC
